// 归档内容损坏（包括第二份报告）：非零退出、原因进 stderr、stdout 不出现
// 比较结果或第一份报告的局部成功片段，更不能把读取失败降级成“未检查”。
func TestCLIDiffCorruptArchiveFailsCleanly(t *testing.T) {
