27	// 不能按不变式。
28	func addedCLIRules() []cliWireRule {
29		return []cliWireRule{
30			{ID: "added-reentrancy", Kind: "static", Severity: "critical", Invariant: "shared-reentrancy-invariant", Version: "8.1.0"},
31			{ID: "existing-reentrancy", Kind: "static", Severity: "medium", Invariant: "shared-reentrancy-invariant", Version: "2.0.4"},
32		}
33	}
34	
35	// TestCLIDiffAddedDefectRuleIsNotNewDefect 在进程边界覆盖核心口径：带缺陷
36	// 新规则在基准报告完全缺席 -> “新增规则”（基准侧 null、新侧证据逐字保留）；
37	// 同份输出中定义一致的对照规则通过 -> 发现缺陷 -> “新发现缺陷”（通过侧无缺
38	// 陷记录）。addedRules 与 newDefects 各为一，两侧缺陷总数为零和二。
39	func TestCLIDiffAddedDefectRuleIsNotNewDefect(t *testing.T) {
40		bin := auditBinary(t)
41		work := t.TempDir()
42		store := filepath.Join(work, "reports")
43		artifact := mixedCheckArtifact()
44		hash := mixedArtifactHash(t)
45		rules := addedCLIRules()
46		addedRule, existingRule := rules[0], rules[1]
47	
48		// 基准报告只包含已有规则，结论为通过；新增规则完全缺席。
49		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
50			[]cliWireRule{existingRule},
51			[]cliWireCheck{
52				{ArtifactHash: hash, RuleID: existingRule.ID, Version: existingRule.Version, Status: contractsentinel.StatusPass},
53			})
54		// 新报告扩大检查范围：新增规则首次出现即发现缺陷，已有规则由通过变为
55		// 发现缺陷；提交顺序刻意与标识排序不同，归属不得受归档排列影响。
56		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
57			[]cliWireRule{existingRule, addedRule},
58			[]cliWireCheck{
59				{ArtifactHash: hash, RuleID: existingRule.ID, Version: existingRule.Version, Status: contractsentinel.StatusDefect, Note: existingRuleEvidence},
60				{ArtifactHash: hash, RuleID: addedRule.ID, Version: addedRule.Version, Status: contractsentinel.StatusDefect, Note: addedRuleEvidence},
61			})
62	
63		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
64		if code != 0 {
65			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
66		}
67		d := decodeDiff(t, stdout)
68	
69		// 报告标识与比较方向按命令行参数保留，两侧为同一产物。
70		if d.Before.ReportID != before.ReportID || d.After.ReportID != after.ReportID {
71			t.Errorf("refs = %q/%q, want %q/%q", d.Before.ReportID, d.After.ReportID, before.ReportID, after.ReportID)
72		}
73		if d.ArtifactNameChanged || d.ArtifactHashChanged {
74			t.Error("same artifact must not be flagged changed")
75		}
76	
77		// 每个标识恰好一个结果，共两条，按标识排序。
78		if len(d.Results) != 2 {
79			t.Fatalf("results = %d, want 2", len(d.Results))
80		}
81		ids := make([]string, 0, len(d.Results))
82		for _, r := range d.Results {
83			ids = append(ids, r.RuleID)
84		}
85		if !sort.StringsAreSorted(ids) {
86			t.Errorf("results not sorted by rule id: %v", ids)
87		}
88	
89		// --- 新增的缺陷规则 ---
90		added := diffEntry(t, d, addedRule.ID)
91		if added.Change != contractsentinel.ChangeRuleAdded {
92			t.Fatalf("added change = %q, want %q", added.Change, contractsentinel.ChangeRuleAdded)
93		}
94		if added.Before != nil {
95			t.Fatalf("absent baseline side must be null, got %+v", added.Before)
96		}
97		if added.After == nil {
98			t.Fatal("added rule must keep its new side")
99		}
100		if ra := added.After.Rule; ra.ID != addedRule.ID || ra.Kind != "static" ||
101			ra.Severity != "critical" || ra.Invariant != "shared-reentrancy-invariant" ||
102			ra.RequiresABI != false || ra.Version != "8.1.0" {
103			t.Errorf("added new-side rule definition = %+v, want the archived definition", ra)
104		}
105		if added.After.Rule.Status != contractsentinel.StatusDefect {
106			t.Errorf("added new-side status = %q, want %q", added.After.Rule.Status, contractsentinel.StatusDefect)
107		}
108		if added.After.Rule.Note != addedRuleEvidence {
109			t.Errorf("added new-side note = %q, want %q verbatim", added.After.Rule.Note, addedRuleEvidence)
110		}
111		af := added.After.Finding
112		if af == nil {
113			t.Fatal("added new side must keep its defect finding")
114		}
115		if af.ArtifactHash != hash || af.RuleID != addedRule.ID || af.Version != addedRule.Version ||
116			af.Severity != "critical" || af.Invariant != "shared-reentrancy-invariant" {
117			t.Errorf("added finding binding = %+v, want hash=%q rule=%q version=%q", af, hash, addedRule.ID, addedRule.Version)
118		}
119		if af.Evidence != addedRuleEvidence {
120			t.Errorf("added evidence = %q, want %q verbatim", af.Evidence, addedRuleEvidence)
121		}
122	
123		// --- 两侧都在的对照规则：定义一致、通过 -> 发现缺陷 ---
124		existing := diffEntry(t, d, existingRule.ID)
125		if existing.Change != contractsentinel.ChangeNewDefect {
126			t.Fatalf("existing change = %q, want %q", existing.Change, contractsentinel.ChangeNewDefect)
127		}
128		if existing.Before == nil || existing.After == nil {
129			t.Fatal("new-defect rule must carry both sides")
130		}
131		if eb := existing.Before.Rule; eb.ID != existingRule.ID || eb.Severity != "medium" ||
132			eb.Version != "2.0.4" || eb.Status != contractsentinel.StatusPass || eb.Note != "" {
133			t.Errorf("existing before = %+v", eb)
134		}
135		if ea := existing.After.Rule; ea.Status != contractsentinel.StatusDefect ||
136			ea.Note != existingRuleEvidence || ea.ID != existingRule.ID || ea.Version != "2.0.4" {
137			t.Errorf("existing after = %+v", ea)
138		}
139		if existing.Before.Finding != nil {
140			t.Errorf("passing baseline side must carry no finding: %+v", existing.Before.Finding)
141		}
142		if existing.After.Finding == nil || existing.After.Finding.Evidence != existingRuleEvidence ||
143			existing.After.Finding.RuleID != existingRule.ID || existing.After.Finding.Version != existingRule.Version ||
144			existing.After.Finding.ArtifactHash != hash {
145			t.Errorf("existing rule must keep its own finding: %+v", existing.After.Finding)
146		}
147		// 两条规则引用同一不变式名，也必须各自保留自己的反例，不能互换证据。
148		if existing.After.Finding.Evidence == addedRuleEvidence {
149			t.Error("existing rule inherited the added rule's evidence; findings must stay bound by rule id")
150		}
151	
152		// --- 汇总：两类变化各计其一，缺陷总数只数各自归档的实际发现 ---
153		s := d.Summary
154		if s.AddedRules != 1 {
155			t.Errorf("addedRules = %d, want 1", s.AddedRules)
156		}
157		if s.NewDefects != 1 {
158			t.Errorf("newDefects = %d, want 1 (the added rule must not inflate this)", s.NewDefects)
159		}
160		if s.ResolvedDefects != 0 || s.StatusChanges != 0 || s.NoteChanges != 0 ||
161			s.NoChange != 0 || s.RemovedRules != 0 || s.ChangedRules != 0 {
162			t.Errorf("every other count must be zero: %+v", s)
163		}
164		if s.BeforeDefects != 0 || s.AfterDefects != 2 {
165			t.Errorf("defect totals = %d/%d, want 0/2 (actual archived findings)", s.BeforeDefects, s.AfterDefects)
166		}
167	
168		// 原始输出字节层面：缺席基准侧渲染为 null，新侧证据中的中文、换行
169		// （JSON 转义为 \n）和前后空白逐字保留。
170		if !strings.Contains(stdout, `"before": null`) {
171			t.Errorf("added entry must render the absent side as null:\n%s", stdout)
172		}
173		if !strings.Contains(stdout, "  新反例：新增规则首次检出\\n  reentrancy 路径第二行  ") {
174			t.Errorf("diff output must preserve the added rule evidence verbatim:\n%s", stdout)
175		}
176		if !strings.Contains(stdout, `"change": "`+contractsentinel.ChangeRuleAdded+`"`) {
177			t.Errorf("diff output must carry the %q category:\n%s", contractsentinel.ChangeRuleAdded, stdout)
178		}
179		if !strings.Contains(stdout, `"change": "`+contractsentinel.ChangeNewDefect+`"`) {
180			t.Errorf("diff output must carry the %q category:\n%s", contractsentinel.ChangeNewDefect, stdout)
181		}
182	}
183	
184	// TestCLIDiffAddedDefectRuleAgainstRuleLessBaseline 基准报告没有任何规则也
185	// 是合法输入：diff 正常退出，新缺陷规则按新增处理，基准侧保持 null 而不是补
186	// 成“通过”，新侧缺陷总数如实计一。
187	func TestCLIDiffAddedDefectRuleAgainstRuleLessBaseline(t *testing.T) {
188		bin := auditBinary(t)
189		work := t.TempDir()
190		store := filepath.Join(work, "reports")
191		artifact := mixedCheckArtifact()
192		hash := mixedArtifactHash(t)
193		addedRule := addedCLIRules()[0]
194	
195		// 基准报告零规则零检查：合法的空范围报告。
196		before := auditDiffReport(t, bin, work, store, "before.json", artifact, nil, nil)
197		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
198			[]cliWireRule{addedRule},
199			[]cliWireCheck{{ArtifactHash: hash, RuleID: addedRule.ID, Version: addedRule.Version,
200				Status: contractsentinel.StatusDefect, Note: addedRuleEvidence}})
201	
202		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
203		if code != 0 {
204			t.Fatalf("diff against a rule-less baseline must succeed, exit=%d stderr=%s", code, stderr)
205		}
206		d := decodeDiff(t, stdout)
207		if len(d.Results) != 1 {
208			t.Fatalf("results = %d, want 1: %+v", len(d.Results), d.Results)
209		}
210		entry := d.Results[0]
211		if entry.RuleID != addedRule.ID || entry.Change != contractsentinel.ChangeRuleAdded {
212			t.Fatalf("entry = %q/%q, want %q/%q", entry.RuleID, entry.Change, addedRule.ID, contractsentinel.ChangeRuleAdded)
213		}
214		if entry.Before != nil {
215			t.Errorf("absent baseline side must be null, not a fabricated pass: %+v", entry.Before)
216		}
217		if entry.After == nil || entry.After.Finding == nil ||
218			entry.After.Finding.Evidence != addedRuleEvidence ||
219			entry.After.Finding.ArtifactHash != hash || entry.After.Finding.Version != addedRule.Version {
220			t.Errorf("new side must keep the archived defect: %+v", entry.After)
221		}
222		s := d.Summary
223		if s.AddedRules != 1 || s.NewDefects != 0 {
224			t.Errorf("summary = %+v, want added=1 newDefects=0", s)
225		}
226		if s.BeforeDefects != 0 || s.AfterDefects != 1 {
227			t.Errorf("defect totals = %d/%d, want 0/1", s.BeforeDefects, s.AfterDefects)
228		}
229		if !strings.Contains(stdout, `"before": null`) {
230			t.Errorf("added entry must render the absent side as null:\n%s", stdout)
231		}
232	}
233	
234	// TestCLIDiffUncheckedBaselineRuleIsNotAdded 明确“新增”的判定边界：基准报告
235	// 已有该规则、只是状态为“未检查”，新报告同一规则发现缺陷时，diff 正常退出并
236	// 按现有规则归为“检查状态变化”，不计入新增规则，也不计入新发现缺陷。
237	func TestCLIDiffUncheckedBaselineRuleIsNotAdded(t *testing.T) {
238		bin := auditBinary(t)
239		work := t.TempDir()
240		store := filepath.Join(work, "reports")
241		artifact := mixedCheckArtifact()
242		hash := mixedArtifactHash(t)
243		rule := addedCLIRules()[0]
244	
245		// 基准侧：规则在但没有任何检查记录 -> 未检查。
246		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
247			[]cliWireRule{rule}, nil)
248		// 新侧：同一条规则定义完全一致，外部检查器发现缺陷。
249		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
250			[]cliWireRule{rule},
251			[]cliWireCheck{{ArtifactHash: hash, RuleID: rule.ID, Version: rule.Version,
252				Status: contractsentinel.StatusDefect, Note: addedRuleEvidence}})
253	
254		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
255		if code != 0 {
256			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
257		}
258		d := decodeDiff(t, stdout)
259		if len(d.Results) != 1 {
260			t.Fatalf("results = %d, want 1: %+v", len(d.Results), d.Results)
261		}
262		entry := d.Results[0]
263		if entry.RuleID != rule.ID || entry.Change != contractsentinel.ChangeStatusChanged {
264			t.Fatalf("entry = %q/%q, want %q/%q (a rule present in the baseline is not an added rule)",
265				entry.RuleID, entry.Change, rule.ID, contractsentinel.ChangeStatusChanged)
266		}
267		if entry.Before == nil || entry.After == nil {
268			t.Fatal("a rule present in both reports must keep both sides")
269		}
270		if entry.Before.Rule.Status != contractsentinel.StatusUnchecked || entry.Before.Finding != nil {
271			t.Errorf("baseline side = %+v, want 未检查 without a finding", entry.Before)
272		}
273		if entry.After.Rule.Status != contractsentinel.StatusDefect ||
274			entry.After.Finding == nil || entry.After.Finding.Evidence != addedRuleEvidence {
275			t.Errorf("new side must keep the archived defect: %+v", entry.After)
276		}
277		s := d.Summary
278		if s.StatusChanges != 1 || s.AddedRules != 0 || s.NewDefects != 0 {
279			t.Errorf("summary = %+v, want statusChanges=1 added=0 newDefects=0", s)
280		}
281		if s.BeforeDefects != 0 || s.AfterDefects != 1 {
282			t.Errorf("defect totals = %d/%d, want 0/1", s.BeforeDefects, s.AfterDefects)
283		}
284	}
