1	package contractsentinel
2	
3	import (
4		"os"
5		"path/filepath"
6		"sort"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件围绕比较功能的一项业务回归口径：新报告扩大检查范围、首次引入某条规则
12	// 且该规则第一次接受检查就发现缺陷时，输出必须为该标识保留一个“新增规则”条
13	// 目——而不是仅凭缺陷总数上升就把它记成已有规则的“新发现缺陷”。规则此前从未
14	// 出现在基准报告中，不存在可比较的基准侧结论：新增条目的基准侧为 null，不能
15	// 补造“通过”结论；新侧必须仍是归档中的完整规则定义、检查状态（发现缺陷）、原
16	// 始说明和缺陷记录。汇总中新增规则数计入这一条，新发现缺陷数不能因此增加；两
17	// 侧缺陷总数只数各自归档中实际存在的缺陷，新侧这条真实缺陷仍计入新侧总数，不
18	// 能为了分类而把它从总数或证据中抹掉。
19	//
20	// 同一份比较结果中保留一条两侧都存在的规则作为对照：定义完全一致、通过 ->
21	// 发现缺陷归为“新发现缺陷”，基准侧 finding 为 null。两条规则即使引用同一个
22	// 不变式名，也按各自规则标识独立呈现，各自保留自己的版本、严重级别与反例，
23	// 不按不变式名合并或互换证据。
24	//
25	// “新增”只依据规则是否出现在基准报告中判断：基准报告已有该规则、只是状态为
26	// “未检查”，后来发现缺陷时仍按现有规则归为“检查状态变化”。基准报告没有任何
27	// 规则也是合法比较条件：新增缺陷规则仍正常呈现，缺席侧保持 null。
28	//
29	// 所有用例都走 BuildReport -> SaveReport -> DiffStore 的正常归档与读回路径，
30	// 比较的是同一产物（同一名称、同一内容哈希）的两份可正常读取的归档报告。
31	
32	// addedRuleEvidence 与 existingRuleEvidence 刻意包含中文、换行与前后空白，且
33	// 互不相同；新增不得改写证据，两条规则也不得互换证据。
34	const addedRuleEvidence = "  新反例：新增规则首次检出\n  reentrancy 路径第二行  "
35	const existingRuleEvidence = "  已有规则复跑反例\n第二行  "
36	
37	// addedPairRules 构造同一份产物上的两条规则：added-reentrancy 在基准报告中
38	// 完全缺席，existing-reentrancy 两侧都在且定义完全一致。两者刻意引用同一个
39	// 不变式名，回归保障必须按规则标识、而非按不变式名归属证据与结论。
40	func addedPairRules() []Rule {
41		return []Rule{
42			{
43				ID:        "added-reentrancy",
44				Kind:      "static",
45				Severity:  "critical",
46				Invariant: "shared-reentrancy-invariant",
47				Version:   "8.1.0",
48			},
49			{
50				ID:        "existing-reentrancy",
51				Kind:      "static",
52				Severity:  "medium",
53				Invariant: "shared-reentrancy-invariant",
54				Version:   "2.0.4",
55			},
56		}
57	}
58	
59	// TestDiffAddedDefectRuleIsAddedNotNewDefect 是核心回归用例：带缺陷的新规则
60	// 在基准报告规则列表中完全缺席，必须记为“新增规则”而非“新发现缺陷”，基准侧
61	// 为 null、新侧完整保留；同报告中定义一致的对照规则通过 -> 发现缺陷记为
62	// “新发现缺陷”。addedRules 与 newDefects 各为一，两侧缺陷总数为零和二。
63	func TestDiffAddedDefectRuleIsAddedNotNewDefect(t *testing.T) {
64		dir := t.TempDir()
65		artifact := sampleArtifact()
66		hash := ArtifactHash(artifact)
67		rules := addedPairRules()
68		addedRule, existingRule := rules[0], rules[1]
69	
70		// 基准报告只包含已有规则，结论为通过；新增规则完全缺席，基准侧零缺陷。
71		before := saveCheckReport(t, dir, artifact, []Rule{existingRule}, []CheckRecord{
72			{ArtifactHash: hash, RuleID: existingRule.ID, Version: existingRule.Version, Status: StatusPass},
73		})
74		// 新报告扩大检查范围：新增规则首次出现即发现缺陷，已有规则由通过变为
75		// 发现缺陷。规则与检查记录的排列顺序刻意与标识排序不同，归属不得受
76		// 归档排列影响。
77		after := saveCheckReport(t, dir, artifact, []Rule{existingRule, addedRule}, []CheckRecord{
78			{ArtifactHash: hash, RuleID: existingRule.ID, Version: existingRule.Version, Status: StatusDefect, Note: existingRuleEvidence},
79			{ArtifactHash: hash, RuleID: addedRule.ID, Version: addedRule.Version, Status: StatusDefect, Note: addedRuleEvidence},
80		})
81	
82		// 两份归档必须能独立读回：基准侧零缺陷，新侧两条真实缺陷。
83		loadedBefore, err := LoadReport(dir, before.ReportID)
84		if err != nil {
85			t.Fatalf("load before: %v", err)
86		}
87		loadedAfter, err := LoadReport(dir, after.ReportID)
88		if err != nil {
89			t.Fatalf("load after: %v", err)
90		}
91		if len(loadedBefore.Findings) != 0 || len(loadedAfter.Findings) != 2 {
92			t.Fatalf("archived findings = %d/%d, want 0/2", len(loadedBefore.Findings), len(loadedAfter.Findings))
93		}
94		ruleIDsBefore := map[string]bool{}
95		for _, r := range loadedBefore.Rules {
96			ruleIDsBefore[r.ID] = true
97		}
98		if ruleIDsBefore[addedRule.ID] {
99			t.Fatalf("baseline must not contain %s", addedRule.ID)
100		}
101	
102		// 比较前留存归档快照：比较全程不得改动任何已保存报告。
103		filesBefore := storeFileNames(t, dir)
104		contentsBefore := map[string]string{}
105		for _, name := range filesBefore {
106			data, err := os.ReadFile(filepath.Join(dir, name))
107			if err != nil {
108				t.Fatal(err)
109			}
110			contentsBefore[name] = string(data)
111		}
112	
113		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
114		if err != nil {
115			t.Fatalf("diff must succeed when the new report adds a defect rule: %v", err)
116		}
117	
118		// 比较方向与报告标识按归档选择保留；同一产物不标记为变化。
119		if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
120			t.Errorf("refs = %q/%q, want %q/%q", diff.Before.ReportID, diff.After.ReportID, before.ReportID, after.ReportID)
121		}
122		if diff.ArtifactHashChanged || diff.ArtifactNameChanged {
123			t.Error("same artifact must not be flagged changed")
124		}
125	
126		// 每个标识只出现一次，共两条结果，且按规则标识排列。
127		if len(diff.Results) != 2 {
128			t.Fatalf("results = %d, want 2: %+v", len(diff.Results), diff.Results)
129		}
130		ids := []string{}
131		for _, r := range diff.Results {
132			ids = append(ids, r.RuleID)
133		}
134		if !sort.StringsAreSorted(ids) {
135			t.Errorf("results not sorted by rule id: %v", ids)
136		}
137		seen := map[string]int{}
138		for _, r := range diff.Results {
139			seen[r.RuleID]++
140		}
141		if seen[addedRule.ID] != 1 || seen[existingRule.ID] != 1 {
142			t.Fatalf("each id must appear exactly once: %v", seen)
143		}
144	
145		// --- 新增的缺陷规则 ---
146		added := entryByID(t, diff, addedRule.ID)
147		if added.Change != ChangeRuleAdded {
148			t.Fatalf("added rule change = %q, want %q", added.Change, ChangeRuleAdded)
149		}
150		if added.Before != nil {
151			t.Fatalf("absent baseline side must be null, got %+v", added.Before)
152		}
153		if added.After == nil {
154			t.Fatal("added rule must keep its new side")
155		}
156		assertRuleFields(t, "added after side", added.After.Rule, addedRule, StatusDefect, addedRuleEvidence)
157		assertFindingBinding(t, "added after side", added.After.Finding, hash, addedRule, addedRuleEvidence)
158	
159		// --- 两侧都在的对照规则：定义一致、通过 -> 发现缺陷 ---
160		existing := entryByID(t, diff, existingRule.ID)
161		if existing.Change != ChangeNewDefect {
162			t.Fatalf("existing rule change = %q, want %q", existing.Change, ChangeNewDefect)
163		}
164		if existing.Before == nil || existing.After == nil {
165			t.Fatal("new-defect rule must carry both sides")
166		}
167		assertRuleFields(t, "existing before side", existing.Before.Rule, existingRule, StatusPass, "")
168		assertRuleFields(t, "existing after side", existing.After.Rule, existingRule, StatusDefect, existingRuleEvidence)
169		if existing.Before.Finding != nil {
170			t.Errorf("passing baseline side must carry no finding: %+v", existing.Before.Finding)
171		}
172		assertFindingBinding(t, "existing after side", existing.After.Finding, hash, existingRule, existingRuleEvidence)
173	
174		// --- 两条规则引用同一不变式名，也必须各自保留自己的版本、严重级别与
175		// 反例，不能按不变式名合并或互换证据 ---
176		if added.After.Finding.Evidence == existingRuleEvidence ||
177			existing.After.Finding.Evidence == addedRuleEvidence {
178			t.Error("each rule must keep its own evidence; findings must not be merged or swapped by invariant name")
179		}
180		if added.After.Finding.RuleID == existing.After.Finding.RuleID {
181			t.Error("findings must stay bound to their own rule ids")
182		}
183		if added.After.Rule.Version == existing.After.Rule.Version ||
184			added.After.Rule.Severity == existing.After.Rule.Severity {
185			t.Error("each rule must keep its own version and severity")
186		}
187	
188		// --- 汇总：新增计入一，新发现缺陷计入一；不能把新增算成新缺陷 ---
189		s := diff.Summary
190		if s.AddedRules != 1 {
191			t.Errorf("addedRules = %d, want 1", s.AddedRules)
192		}
193		if s.NewDefects != 1 {
194			t.Errorf("newDefects = %d, want 1 (the added rule must not inflate this)", s.NewDefects)
195		}
196		if s.ResolvedDefects != 0 || s.StatusChanges != 0 || s.NoteChanges != 0 ||
197			s.NoChange != 0 || s.RemovedRules != 0 || s.ChangedRules != 0 {
198			t.Errorf("every other count must be zero: %+v", s)
199		}
200		// 两侧缺陷总数只数各自归档中实际存在的缺陷：基准侧 0、新侧 2；新增
201		// 规则的真实缺陷仍计入新侧总数，不能为了分类而排除。
202		if s.BeforeDefects != 0 || s.AfterDefects != 2 {
203			t.Errorf("defect totals = %d/%d, want 0/2 (actual archived findings)", s.BeforeDefects, s.AfterDefects)
204		}
205	
206		// 比较是只读操作：归档文件集合与内容保持原样。
207		filesAfter := storeFileNames(t, dir)
208		if strings.Join(filesBefore, ",") != strings.Join(filesAfter, ",") {
209			t.Fatalf("store files changed: %v -> %v", filesBefore, filesAfter)
210		}
211		for _, name := range filesAfter {
212			data, err := os.ReadFile(filepath.Join(dir, name))
213			if err != nil {
214				t.Fatal(err)
