// filteredPair 归档同一产物上的两份报告：selected 是被筛选的规则，
// other 是同一份报告中另一条始终缺陷的对照规则；两侧各给一组检查状态。
func filteredPair(t *testing.T, dir string,
	selectedStatus, selectedNote, otherStatus, otherNote string) (Report, Report) {
	t.Helper()
	artifact := sampleArtifact()
	hash := ArtifactHash(artifact)
	rules := []Rule{
		{ID: "selected", Kind: "static", Severity: "high", Invariant: "inv-selected", Version: "1"},
		{ID: "other", Kind: "static", Severity: "medium", Invariant: "inv-other", Version: "1"},
	}
	checks := func(selectedStatus, selectedNote, otherStatus, otherNote string) []CheckRecord {
		out := []CheckRecord{
			{ArtifactHash: hash, RuleID: "selected", Version: "1", Status: selectedStatus, Note: selectedNote},
		}
		// 空状态表示该侧不放 other 的检查记录（未检查），由调用方避免。
		if otherStatus != "" {
			out = append(out, CheckRecord{ArtifactHash: hash, RuleID: "other", Version: "1", Status: otherStatus, Note: otherNote})
		}
		return out
	}
	before := filteredCheckReport(t, dir, artifact, rules, checks(selectedStatus, selectedNote, otherStatus, otherNote))
	return before, Report{}
}

